// Severity Mapper: Datadog priority (P1-P5) to Cisco 7-tier severity
const body = $input.first().json.body || $input.first().json;
const priority = (body.priority || 'P3').toUpperCase();

const severityMap = {
  'P1': { level: 0, name: 'Emergency', emoji: '\ud83d\udfe5' },
  'P2': { level: 2, name: 'Critical', emoji: '\ud83d\udfe0' },
  'P3': { level: 3, name: 'Error', emoji: '\ud83d\udfe1' },
  'P4': { level: 4, name: 'Warning', emoji: '\u26a0\ufe0f' },
  'P5': { level: 5, name: 'Notice', emoji: '\u2139\ufe0f' }
};

const severity = severityMap[priority] || severityMap['P3'];

// Only proceed for Sev 0-2 (Emergency, Alert, Critical)
const shouldAlert = severity.level <= 2;

return [{
  json: {
    ...body,
    severity_level: severity.level,
    severity_name: severity.name,
    severity_emoji: severity.emoji,
    should_alert: shouldAlert,
    original_priority: priority
  }
}];

// DND Check: 10 PM - 8:30 AM ET
// During DND: only Sev 0 (Emergency) proceeds
// Outside DND: Sev 0-2 all proceed

const item = $input.first().json;

// Get current time in America/New_York
const now = new Date();
const etOptions = { timeZone: 'America/New_York', hour: 'numeric', minute: 'numeric', hour12: false };
const etTime = new Intl.DateTimeFormat('en-US', etOptions).format(now);
const [hourStr, minStr] = etTime.split(':');
const hour = parseInt(hourStr);
const minute = parseInt(minStr);
const timeDecimal = hour + (minute / 60);

// DND: 22:00 (10 PM) to 08:30 (8:30 AM)
const isDND = timeDecimal >= 22 || timeDecimal < 8.5;

// During DND, only Emergency (Sev 0) proceeds
const shouldProceed = !isDND || item.severity_level === 0;

return [{
  json: {
    ...item,
    is_dnd: isDND,
    dnd_override: isDND && item.severity_level === 0,
    should_proceed: shouldProceed,
    current_time_et: etTime
  }
}];

// Format Telegram message
const item = $input.first().json;

const status = (item.alert_status || 'Unknown').toLowerCase();
const statusIcon = status === 'recovered' ? '\u2705' : (status === 'triggered' ? '\ud83d\udea8' : '\u2753');

let msg = `${item.severity_emoji} <b>${item.severity_name}</b> | ${statusIcon} ${item.alert_status || 'Unknown'}\n\n`;
msg += `<b>${item.alert_title || 'Datadog Alert'}</b>\n\n`;

if (item.event_msg) {
  msg += `<b>Details:</b> ${item.event_msg}\n\n`;
}

if (item.tags) {
  msg += `<b>Tags:</b> <code>${item.tags}</code>\n`;
}

if (item.link) {
  msg += `\n<a href=\"${item.link}\">View in Datadog</a>`;
}

if (item.is_dnd && item.dnd_override) {
  msg += `\n\n\u26a1 <i>DND override: Emergency alert at ${item.current_time_et} ET</i>`;
}

// Truncate if needed
if (msg.length > 3500) {
  msg = msg.substring(0, 3450) + '\n\n... <i>[Full alert in Datadog]</i>';
}

return [{
  json: {
    telegram_text: msg
  }
}];
